UPDATE draft_order_info
SET
    draft_total_amount = #{draft_total_amount},
    draft_total_quantity = #{draft_total_quantity}
WHERE order_info_id = #{order_info_id}

UPDATE order_item
SET
  product_id = #{product_id},
  product_name = #{product_name},
  quantity = #{quantity},
  price_per_unit = #{price_per_unit}
WHERE order_info_id = #{order_info_id}
  AND order_item_id = #{order_item_id}

mapper.select:
SELECT op.name AS person_name, op.email AS person_email, op.phone AS person_phone, oi2.product_id AS item_product_id, oi2.product_name AS item_product_name, oi2.quantity AS item_quantity, oi2.price_per_unit AS item_price_per_unit, p.payment_id, p.order_info_id AS payment_order_info_id, p.payment_number, p.amount AS payment_amount, p.payment_method, p.created_at AS payment_created_at FROM order_item oi2 JOIN order_person op ON oi2.order_info_id = op.order_info_id JOIN payment p ON oi2.order_info_id = p.order_info_id WHERE oi2.order_info_id IN
#{id}
ORDER BY oi2.order_info_id DESC, p.created_at DESC
